/**
 * DetailCardGrid — Renders product detail data as a structured card grid.
 *
 * Supports visual hierarchy: status badges, price highlights, weight values,
 * and plain-text descriptions. Fields are configured via a props array for
 * flexible layout control.
 */

import type { ProductDetail, DetailFieldConfig } from '../types.js'

interface DetailCardGridProps {
  /** The product detail data to render */
  detail: ProductDetail
  /** Field configuration defining which fields to show and how */
  fields: DetailFieldConfig[]
}

export function DetailCardGrid({ detail, fields }: DetailCardGridProps) {
  if (fields.length === 0) return null

  const getValue = (field: DetailFieldConfig): unknown => {
    return (detail as unknown as Record<string, unknown>)[field.key]
  }

  const shouldShow = (value: unknown, fieldConfig: DetailFieldConfig): boolean => {
    if (!fieldConfig.conditional) return true
    // Show only when value is non-null and non-empty
    if (value == null) return false
    if (typeof value === 'string' && value.trim() === '') return false
    if (typeof value === 'number' && isNaN(value)) return false
    return true
  }

  const renderValue = (field: DetailFieldConfig, value: unknown): React.ReactNode => {
    // Custom render function takes priority
    if (field.render) {
      return field.render(value, detail)
    }

    // Default rendering based on variant
    switch (field.variant) {
      case 'badge':
        return (
          <span className="inline-flex items-center px-2 py-0.5 rounded-full text-xs font-medium bg-green-100 text-green-800">
            {String(value)}
          </span>
        )

      case 'price-highlight': {
        const num = typeof value === 'number' ? value : parseFloat(String(value))
        if (isNaN(num)) return String(value) || '—'
        return <span className="text-lg font-bold text-green-700">€{num.toFixed(2)}</span>
      }

      case 'weight': {
        const num = typeof value === 'number' ? value : parseFloat(String(value))
        if (isNaN(num)) return String(value) || '—'
        return <span className="text-sm font-medium">{num} kg</span>
      }

      default:
        // Plain text for descriptions and regular fields
        if (value == null) return <span className="text-muted-foreground">—</span>
        if (typeof value === 'string') {
          return <p className="leading-relaxed">{value}</p>
        }
        return String(value)
    }
  }

  return (
    <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-4" role="region">
      {fields.map(field => {
        const value = getValue(field)
        if (!shouldShow(value, field)) return null

        return (
          <div
            key={String(field.key)}
            className="bg-card border rounded-lg p-3 shadow-sm"
            role="region"
            aria-label={field.label}
          >
            <dt className="text-xs font-medium text-muted-foreground uppercase tracking-wide mb-1">
              {field.label}
            </dt>
            <dd className="mt-0.5">
              {renderValue(field, value)}
            </dd>
          </div>
        )
      })}
    </div>
  )
}

